class Solution:
    def countPairs(self, deliciousness: List[int]) -> int:
        ans = 0
        n = len(deliciousness)
        for i in range(n):
            for j in range(i + 1, n):
                s = deliciousness[i] + deliciousness[j]
                if s and s & (s - 1) == 0:
                    ans += 1
        return ans % (10 ** 9 + 7)

