from collections import Counter


class Solution:
    def countPairs(self, deliciousness: List[int]) -> int:
        MOD = 10 ** 9 + 7
        cnt = Counter()
        ans = 0
        for d in deliciousness:
            for p in range(22):
                ans += cnt[(1 << p) - d]
            cnt[d] += 1
        return ans % MOD

