class Solution {
public:
    int countPairs(vector<int>& deliciousness) {
        const int MOD = 1e9 + 7;
        unordered_map<int, long> cnt;
        long ans = 0;
        for (int d : deliciousness) {
            for (int p = 0; p <= 21; ++p) {
                auto it = cnt.find((1L << p) - d);
                if (it != cnt.end()) ans += it->second;
            }
            ++cnt[d];
        }
        return (int)(ans % MOD);
    }
};

