class Solution {
    public int countPairs(int[] deliciousness) {
        final int MOD = 1_000_000_007;
        Map<Integer, Integer> cnt = new HashMap<>();
        long ans = 0;
        for (int d : deliciousness) {
            for (int p = 0; p <= 21; p++) {
                Integer c = cnt.get((1 << p) - d);
                if (c != null) ans += c;
            }
            cnt.merge(d, 1, Integer::sum);
        }
        return (int) (ans % MOD);
    }
}

